-- ms.chats select (line 74): read or join or setup
CREATE POLICY "authz_select" ON "ms"."chats" FOR SELECT TO ms_app
  USING (((SELECT authz_int.scope_cmd('ms.chats', 'select')) AND ((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = "chats"."id")
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = "chats"."id"))
    OR ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__invitee" v WHERE v.id = "chats"."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = "chats"."id")))
    OR (coalesce("chats"."created_by" = (SELECT authz.uid()), false)
    AND authz_int."chat__check_ecbdd5ff4d"(ROW("chats".*)::"ms"."chats")))));
COMMENT ON POLICY "authz_select" ON "ms"."chats" IS 'rowstile';

-- ms.chats update (line 76): manage
CREATE POLICY "authz_update" ON "ms"."chats" FOR UPDATE TO ms_app
  USING (((SELECT authz_int.scope_cmd('ms.chats', 'update')) AND (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = "chats"."id"))))
  WITH CHECK (((SELECT authz_int.scope_cmd('ms.chats', 'update')) AND (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = "chats"."id")))
    OR authz_gen."ms.chats:update:refuse"(ROW("chats".*)::"ms"."chats"));
COMMENT ON POLICY "authz_update" ON "ms"."chats" IS 'rowstile';

-- ms.chats delete (line 78): owner and {kind = 'group'}
CREATE POLICY "authz_delete" ON "ms"."chats" FOR DELETE TO ms_app
  USING (((SELECT authz_int.scope_cmd('ms.chats', 'delete')) AND (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__owner" v WHERE v.id = "chats"."id"))));
COMMENT ON POLICY "authz_delete" ON "ms"."chats" IS 'rowstile';

-- ms.members: no row has the id, or the user may select it (what the rules' explanations answer for)
CREATE FUNCTION authz_int."ms.members:seen"(p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN NOT EXISTS (SELECT 1 FROM "ms"."members" o WHERE (o."chat_id", o."user_id") = (((p_id)::authz_gen."membership__key")."chat_id", ((p_id)::authz_gen."membership__key")."user_id"))
      OR EXISTS (SELECT 1 FROM "ms"."members" "members" WHERE ("members"."chat_id", "members"."user_id") = (((p_id)::authz_gen."membership__key")."chat_id", ((p_id)::authz_gen."membership__key")."user_id")
        AND (SELECT authz_int.scope_cmd('ms.members', 'select')) AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = "members"."chat_id"));
END $f$;

CREATE FUNCTION authz_gen."ms.members:insert:items"(p_row "ms"."members") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT CASE WHEN authz_int."ms.members:seen"(ROW("members"."chat_id"::bigint, "members"."user_id"::uuid)::text) THEN ARRAY[
    coalesce(((EXISTS (SELECT 1 FROM authz_int."chat__add_members" v WHERE v.id = "members"."chat_id")
    AND (coalesce((role = 'member'), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__setup" v WHERE v.id = "members"."chat_id")
    OR (coalesce((role <> 'owner'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = "members"."chat_id")))
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_int."user__has_blocked" v WHERE v.id = "members"."user_id"), false))
    OR (coalesce("members"."user_id" = (SELECT authz.uid()), false)
    AND coalesce((role = 'member'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__join" v WHERE v.id = "members"."chat_id"))), false),
    coalesce((SELECT authz_int.scope_cmd('ms.members', 'insert')), false),
    coalesce(true, false),
    coalesce((EXISTS (SELECT 1 FROM authz_int."chat__add_members" v WHERE v.id = "members"."chat_id")
    AND (coalesce((role = 'member'), false)
